=Translate the email below into plain, natural English for an internal reviewer who does not read Turkish. Keep the meaning, paragraph structure, signature, data-source sentence and opt-out sentence exactly; do not improve, shorten or add anything. Return only the translated email text, no preface.
If the email is already in English, reply with exactly: n/a

Subject: {{ $json.output.subject }}

{{ $json.output.body }}

parameters.jsCode:
// Chooses which leads get a first-email draft in this run (Nil's decisions of 23 Nov 2026).
// 1. Second contacts ('Waiting - 2nd contact' rows): drafted two days after the first person was mailed, so the
//    draft is approved in time; WF3 only sends it when three days have passed without a reply. If the first
//    person's mail bounced, the second person is drafted straight away.
// 2. Companies in stage 'Researched' that WF1 has classified under the new rules ('Contact Source' filled):
//    wave 1 (EU-exporting garment makers, integrated groups) or brands, not a bespoke account.
// Wave 2, sourcing offices and bespoke accounts get no automatic draft.
const all = $input.all();
const byId = {};
for (const i of all) { const id = String((i.json || {})['Lead ID'] || '').trim(); if (id) byId[id] = i.json; }
const today = $now.setZone('Europe/Istanbul').toISODate();
const isBrand = (j) => /^(marka|brand)$/i.test(String(j.Segment || '').trim());
const second = [];
const first = [];
for (const i of all) {
  const j = i.json || {};
  const stage = String(j.Stage || '').trim();
  const pid = String(j['Parent Lead ID'] || '').trim();
  if (stage === 'Waiting - 2nd contact' && pid) {
    const p = byId[pid];
    if (!p) continue;
    if (p.Stage === 'Bounced') { second.push(i); continue; }
    if (String(p['Reply Category'] || '').trim() || p['Opt-out'] === 'Yes') continue;
    if (!['Sent', 'Follow-up 1', 'Follow-up 2', 'Follow-up 3'].includes(p.Stage)) continue;
    const t = DateTime.fromISO(String(p['Sent At'] || '').trim());
    if (t.isValid && t.setZone('Europe/Istanbul').plus({ days: 2 }).toISODate() <= today) second.push(i);
  } else if (stage === 'Researched' && !pid) {
    if (!String(j['Contact Source'] || '').trim()) continue;
    if (String(j.Bespoke || '').trim().toLowerCase() === 'yes') continue;
    if (String(j.Wave || '').trim() === '1' || isBrand(j)) first.push(i);
  }
}
return second.concat(first);

// Builds the first email from fixed parts (Nil's decisions of 23 Nov 2026). The model only supplies the person's name,
// the one personal sentence, a short supporting paragraph (exporters) and the subject (exporters). Everything else is
// fixed text: the value sentence (Settings 'Value Prop ...'), the 30-minute demo offer, the calendar link
// (Settings 'Calendar Link'), the sign-off, the signature and the footer. Brands get Nil's full template (section 14).
// Language follows the company's country: Turkey = Turkish, everywhere else English.
const lead = $('Compliance check').item.json;
const s = $('Read Settings').first().json || {};
const o = $input.item.json.output || {};
const clean = (x) => String(x || '').replace(/\s+/g, ' ').trim();
const lang = ['turkey', 'türkiye', 'turkiye'].includes(String(lead.Country || '').trim().toLowerCase()) ? 'tr' : 'en';
const brand = /^(marka|brand)$/i.test(String(lead.Segment || '').trim());
const cal = clean(s['Calendar Link']);
const full = clean(o.person_full_name);
const first = clean(o.person_first_name) || full.split(' ')[0];
const co = clean(o.company_short) || clean(lead.Company);
const greeting = lang === 'tr' ? (full ? 'Sayın ' + full + ',' : 'Sayın ' + co + ' ekibi,') : (full ? 'Dear ' + first + ',' : 'Dear ' + co + ' team,');
const opening = clean(o.opening);
const support = clean(o.support);
const sig = [s['Sender Name'], s['Sender Title'], s['Company Legal Name'], String(s['Company Address'] || '').trim(), s['Company Website'] || 'https://www.texprove.com'].map(x => String(x || '').trim()).filter(Boolean).join('\n');
const source = lang === 'tr' ? 'İletişim bilgilerinizi şirketinizin herkese açık web sitesinden aldık.' : "We found your contact details on your company's public website.";
const optOut = clean(lang === 'tr' ? s['Opt-out TR'] : s['Opt-out EN']);
const closing = lang === 'tr' ? 'Saygılarımla,' : 'Kind regards,';
const cta = lang === 'tr'
  ? 'Sizin sipariş akışınıza benzer bir örnek üzerinden 30 dakikalık canlı bir demo göstermek isterim. Size uygun zamanı buradan seçebilirsiniz: ' + cal
  : 'Could I show you this in a 30-minute live demo, built on an example close to your own order flow? You can pick a time here: ' + cal;

let subject, parts;
if (brand && lang === 'en') {
  subject = 'Supplier data ' + co + ' can stand behind';
  parts = [greeting, opening,
    'The legal responsibility sits with ' + co + '. The data sits with your suppliers. The Digital Product Passport (textile rules expected in 2027), the EU forced labour ban (from 14 December 2027) and textile EPR (national schemes due by April 2028) all ask for the same supplier data.',
    'TexProve gives brands one platform to request and verify it:',
    "- One verified source instead of email and Excel.\n- A document and an auditor's approval behind every claim.\n- Suppliers share the evidence without opening up their network, so they join faster. Joining is free for them.",
    'TexProve is an official GS1 Türkiye Solution Partner.', cta];
} else if (brand) {
  subject = 'Arkasında durabileceğiniz tedarikçi verisi';
  parts = [greeting, opening,
    "Yasal sorumluluk markada, veri ise tedarikçilerde. Dijital ürün pasaportu (tekstil düzenlemesi 2027'de bekleniyor), AB zorla çalıştırma yasağı (14 Aralık 2027'den itibaren) ve tekstilde genişletilmiş üretici sorumluluğu (ulusal sistemler Nisan 2028'e kadar) aynı tedarikçi verisini istiyor.",
    'TexProve, markalara bu veriyi tek platformdan talep edip doğrulama imkânı verir:',
    '- E-posta ve Excel yerine tek doğrulanmış kaynak.\n- Her beyanın arkasında belge ve denetçi onayı.\n- Tedarikçiniz ağını açmadan kanıtı paylaşır, bu yüzden sisteme daha hızlı katılır. Tedarikçi katılımı ücretsizdir.',
    'TexProve, GS1 Türkiye çözüm ortağıdır.', cta];
} else {
  subject = clean(o.subject);
  parts = [greeting, opening, clean(lang === 'tr' ? s['Value Prop Exporter TR'] : s['Value Prop Exporter EN']), support, cta];
}
const body = opening ? [...parts, closing, sig, source, optOut].filter(Boolean).join('\n\n') : '';
return { json: { ...$input.item.json, output: { subject, body }, draft_lang: lang, draft_audience: brand ? 'brand' : 'exporter' } };
